import re


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    # Parse and validate current version
    parts = current.split('.')
    if len(parts) != 3:
        raise ValueError(f"Invalid version: {current}")

    try:
        major, minor, patch = [int(p) for p in parts]
    except ValueError:
        raise ValueError(f"Invalid version: {current}")

    # Check for leading zeros
    if str(major) != parts[0] or str(minor) != parts[1] or str(patch) != parts[2]:
        raise ValueError(f"Invalid version: {current}")

    # Analyze commits to find the strongest change type
    change_type = None  # None, 'fix', 'feature', or 'breaking'

    for commit in commits:
        lines = commit.split('\n')
        header = lines[0]

        # Parse header: must match type: text or type(scope): text
        # type: lowercase letters only
        # scope: anything but parentheses, not empty
        # exactly one space after colon
        # optional ! before colon for breaking change
        pattern = r'^([a-z]+)(?:\(([^()]+)\))?!?: '
        match = re.match(pattern, header)

        if not match:
            continue  # This header doesn't count

        type_name = match.group(1)

        # Check for breaking change markers
        is_breaking_in_header = '!' in header[:header.index(':')]

        is_breaking_in_body = False
        for line in lines[1:]:
            if line.startswith('BREAKING CHANGE: ') or line.startswith('BREAKING-CHANGE: '):
                is_breaking_in_body = True
                break

        is_breaking = is_breaking_in_header or is_breaking_in_body

        # Determine change type for this commit
        commit_change = None
        if is_breaking:
            commit_change = 'breaking'
        elif type_name == 'feat':
            commit_change = 'feature'
        elif type_name == 'fix':
            commit_change = 'fix'

        # Update to the strongest change (breaking > feature > fix)
        if commit_change:
            if commit_change == 'breaking':
                change_type = 'breaking'
            elif commit_change == 'feature' and change_type != 'breaking':
                change_type = 'feature'
            elif commit_change == 'fix' and change_type is None:
                change_type = 'fix'

    # Apply the version bump
    if change_type is None:
        return current

    if major >= 1:
        # 1.0.0 and above
        if change_type == 'breaking':
            return f"{major + 1}.0.0"
        elif change_type == 'feature':
            return f"{major}.{minor + 1}.0"
        elif change_type == 'fix':
            return f"{major}.{minor}.{patch + 1}"
    else:
        # 0.x.x (MAJOR is 0)
        if change_type == 'breaking':
            return f"0.{minor + 1}.0"
        elif change_type == 'feature' or change_type == 'fix':
            return f"0.{minor}.{patch + 1}"

    return current
